type Vertex struct {
	Value string
	Next  []*Vertex
}

func CloneReachable(root *Vertex) *Vertex {
	if root == nil {
		return nil
	}

	clones := make(map[*Vertex]*Vertex)
	var clone func(*Vertex) *Vertex
	clone = func(vertex *Vertex) *Vertex {
		if vertex == nil {
			return nil
		}
		if existing, ok := clones[vertex]; ok {
			return existing
		}

		copyVertex := &Vertex{
			Value: vertex.Value,
			Next:  make([]*Vertex, len(vertex.Next)),
		}
		clones[vertex] = copyVertex
		for i, next := range vertex.Next {
			copyVertex.Next[i] = clone(next)
		}
		return copyVertex
	}

	return clone(root)
}

