public final class Solution {
    private Solution() {
    }

    public static int fingerprintDistinctBytes(byte[] data) {
        int fingerprint = 0;
        long[] seen = new long[4];

        for (byte value : data) {
            int unsigned = value & 0xFF;
            int word = unsigned >>> 6;
            long marker = 1L << (unsigned & 63);
            if ((seen[word] & marker) != 0L) {
                continue;
            }
            seen[word] |= marker;

            fingerprint = ((fingerprint << 3) | (fingerprint >>> 13)) & 0xFFFF;
            fingerprint ^= (unsigned << 8) | unsigned;
        }

        return fingerprint;
    }
}

