import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.StringJoiner;

public final class Solution {
    private Solution() {
    }

    private enum State {
        CREATED, RUNNING, DONE, CANCELLED
    }

    public static String[] manage(String[] commands) {
        Map<String, State> jobs = new LinkedHashMap<>();
        List<String> output = new ArrayList<>();

        for (String command : commands) {
            if (command.equals("LIST")) {
                StringJoiner listing = new StringJoiner(";");
                for (Map.Entry<String, State> entry : jobs.entrySet()) {
                    listing.add(entry.getKey() + "=" + entry.getValue());
                }
                output.add(listing.toString());
                continue;
            }

            int separator = command.indexOf(' ');
            String action = command.substring(0, separator);
            String id = command.substring(separator + 1);

            if (action.equals("CREATE")) {
                jobs.put(id, State.CREATED);
            } else {
                State state = jobs.get(id);
                if (action.equals("START") && state == State.CREATED) {
                    jobs.put(id, State.RUNNING);
                } else if (action.equals("COMPLETE") && state == State.RUNNING) {
                    jobs.put(id, State.DONE);
                } else if (action.equals("CANCEL")
                        && (state == State.CREATED || state == State.RUNNING)) {
                    jobs.put(id, State.CANCELLED);
                }
            }
            output.add(id + "=" + jobs.get(id));
        }

        return output.toArray(new String[0]);
    }
}

