import java.text.Normalizer;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

public final class Solution {
    public static List<String> registerAndFind(List<String> proposedNames, String query) {
        List<String> names = new ArrayList<String>();
        List<String> keys = new ArrayList<String>();
        Set<String> seen = new HashSet<String>();

        for (String proposedName : proposedNames) {
            String display = clean(proposedName);
            if (display.isEmpty() || display.codePointCount(0, display.length()) > 20) {
                throw new IllegalArgumentException("invalid member name");
            }
            String key = key(display);
            if (seen.add(key)) {
                names.add(display);
                keys.add(key);
            }
        }

        String cleanedQuery = clean(query);
        if (cleanedQuery.isEmpty()) {
            throw new IllegalArgumentException("blank query");
        }
        String queryKey = key(cleanedQuery);
        List<String> matches = new ArrayList<String>();
        for (int i = 0; i < names.size(); i++) {
            if (keys.get(i).contains(queryKey)) {
                matches.add(names.get(i));
            }
        }
        return matches;
    }

    private static String key(String value) {
        return Normalizer.normalize(value.toLowerCase(Locale.ROOT), Normalizer.Form.NFC);
    }

    private static String clean(String value) {
        String normalized = Normalizer.normalize(value, Normalizer.Form.NFC);
        int start = 0;
        int end = normalized.length();
        while (start < end) {
            int cp = normalized.codePointAt(start);
            if (!isUnicodeSpace(cp)) {
                break;
            }
            start += Character.charCount(cp);
        }
        while (end > start) {
            int cp = normalized.codePointBefore(end);
            if (!isUnicodeSpace(cp)) {
                break;
            }
            end -= Character.charCount(cp);
        }
        return normalized.substring(start, end);
    }

    private static boolean isUnicodeSpace(int codePoint) {
        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);
    }
}

