const calculateFees = (amounts, rateBasisPoints) => {
  if (!Array.isArray(amounts)) {
    return null;
  }
  if (
    !Number.isSafeInteger(rateBasisPoints) ||
    rateBasisPoints < 0 ||
    rateBasisPoints > 10000
  ) {
    return null;
  }
  if (amounts.some((amount) => !Number.isSafeInteger(amount) || amount < 0)) {
    return null;
  }

  const rate = BigInt(rateBasisPoints);
  return amounts.map((amount) => {
    const scaled = BigInt(amount) * rate;
    return Number((scaled + 5000n) / 10000n);
  });
};

module.exports = { calculateFees };

const assignBuckets = (values, lowerBound, upperBound, bucketCount) => {
  if (!Array.isArray(values)) {
    return null;
  }
  if (
    !Number.isFinite(lowerBound) ||
    !Number.isFinite(upperBound) ||
    lowerBound >= upperBound ||
    !Number.isSafeInteger(bucketCount) ||
    bucketCount <= 0 ||
    values.some((value) => !Number.isFinite(value))
  ) {
    return null;
  }

  const width = upperBound - lowerBound;
  return values.map((value) => {
    if (value <= lowerBound) {
      return 0;
    }
    if (value >= upperBound) {
      return bucketCount - 1;
    }
    return Math.floor(((value - lowerBound) / width) * bucketCount);
  });
};

module.exports = { assignBuckets };

