export interface BinaryChunk {
  readonly tag: number;
  readonly bytes: Uint8Array;
}

export function encodeChunks(chunks: readonly BinaryChunk[]): Uint8Array {
  const ordered = chunks
    .map((chunk, position) => ({ chunk, position }))
    .sort((left, right) =>
      left.chunk.tag - right.chunk.tag || left.position - right.position,
    );

  const encoded: number[] = [];
  let checksum = 0;

  const append = (byte: number): void => {
    encoded.push(byte);
    checksum ^= byte;
  };

  for (const { chunk } of ordered) {
    append(chunk.tag);
    append((chunk.bytes.length >>> 8) & 0xff);
    append(chunk.bytes.length & 0xff);
    for (const byte of chunk.bytes) {
      append(byte);
    }
  }

  encoded.push(checksum & 0xff);
  return Uint8Array.from(encoded);
}

export function encodeTaggedRecords(
    records: ReadonlyArray<{
        priority: number;
        kind: number;
        flags: readonly boolean[];
        payload: Uint8Array;
    }>,
): Uint8Array {
    const ordered = records
        .map((record, index) => ({ record, index }))
        .sort((a, b) =>
            a.record.priority === b.record.priority
                ? a.index - b.index
                : a.record.priority - b.record.priority,
        );

    let totalLength = 0;
    for (const { record } of ordered) {
        totalLength += 4 + record.payload.length;
    }

    const output = new Uint8Array(totalLength);
    let offset = 0;

    for (const { record } of ordered) {
        let mask = 0;
        for (let bit = 0; bit < 8; bit++) {
            if (record.flags[bit]) {
                mask |= 1 << bit;
            }
        }

        const length = record.payload.length;
        let checksum = record.kind ^ mask ^ length;
        output[offset++] = record.kind;
        output[offset++] = mask;
        output[offset++] = length;

        for (const byte of record.payload) {
            output[offset++] = byte;
            checksum ^= byte;
        }

        output[offset++] = checksum;
    }

    return output;
}

