      throw new Error(`invalid transition: ${this.state} -> ${type}`);
    }

    if (type === "START") {
      this.documentId = nextDocumentId;
      this.decisionNote = null;
      this.state = "REVIEWING";
    } else if (type === "DECIDE") {
      this.decisionNote = note;
      this.state = approved === true ? "ACCEPTED" : "REJECTED";
    } else {
      this.state = "IDLE";
      this.documentId = null;
      this.decisionNote = null;
    }

    return this.view();
  }

