export interface TextSnapshot {
  readonly text: string;
  readonly codePoints: number;
  readonly words: number;
}

export class TextAccumulator {
  private text = "";

  append(input: string): TextSnapshot {
    const fragment = input
      .normalize("NFKC")
      .replace(/\p{White_Space}+/gu, " ")
      .trim();

    if (fragment.length > 0) {
      this.text = this.text.length === 0 ? fragment : `${this.text} ${fragment}`;
    }
    return this.snapshot();
  }

  clear(): TextSnapshot {
    this.text = "";
    return this.snapshot();
  }

  snapshot(): TextSnapshot {
    const words = this.text.match(/[\p{L}\p{M}\p{N}]+/gu) ?? [];
    return {
      text: this.text,
      codePoints: Array.from(this.text).length,
      words: words.length
    };
  }
}

