import heapq


def unlock_order(tasks, prerequisites):
    positions = {task: index for index, task in enumerate(tasks)}
    children = {task: [] for task in tasks}
    indegree = {task: 0 for task in tasks}
    seen_edges = set()

    for prerequisite, dependent in prerequisites:
        edge = (prerequisite, dependent)
        if edge not in seen_edges:
            seen_edges.add(edge)
            children[prerequisite].append(dependent)
            indegree[dependent] += 1

    ready = [positions[task] for task in tasks if indegree[task] == 0]
    heapq.heapify(ready)
    order = []

    while ready:
        index = heapq.heappop(ready)
        task = tasks[index]
        order.append(task)
        for dependent in children[task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, positions[dependent])

    return tuple(order)

def dependency_layers(graph: dict[str, list[str]], starts: list[str]) -> list[list[str]]:
    current = []
    discovered = set()
    for node in starts:
        if node not in discovered:
            discovered.add(node)
            current.append(node)

    layers = []
    while current:
        layers.append(current[:])
        next_layer = []
        for node in current:
            for child in graph[node]:
                if child not in discovered:
                    discovered.add(child)
                    next_layer.append(child)
        current = next_layer
    return layers

