            raise ValueError("operation must be a nonempty tuple")

        name = operation[0]
        if name == "set":
            if len(operation) != 3 or not _is_index(operation[1]):
                raise ValueError("malformed set")
            index = operation[1]
            if index < 0 or index >= len(result):
                raise ValueError("set index out of bounds")
            result[index] = operation[2]
        elif name == "insert":
            if len(operation) != 3 or not _is_index(operation[1]):
                raise ValueError("malformed insert")
            index = operation[1]
            if index < 0 or index > len(result):
                raise ValueError("insert index out of bounds")
            result.insert(index, operation[2])
        elif name == "delete":
            if len(operation) != 2 or not _is_index(operation[1]):
                raise ValueError("malformed delete")
            index = operation[1]
            if index < 0 or index >= len(result):
                raise ValueError("delete index out of bounds")
            del result[index]
        elif name == "move":
            if len(operation) != 4 or not all(_is_index(item) for item in operation[1:]):
                raise ValueError("malformed move")
            start, count, destination = operation[1:]
            if start < 0 or count <= 0 or start + count > len(result):
                raise ValueError("move range out of bounds")
            remaining_length = len(result) - count
            if destination < 0 or destination > remaining_length:
                raise ValueError("move destination out of bounds")
            block = result[start:start + count]
            del result[start:start + count]
            result[destination:destination] = block
        else:
            raise ValueError("unknown operation")

