    return result

import copy as _copy


def make_document_workflow(initial_document):
    committed = _copy.deepcopy(initial_document)
    staged = None
    state = "idle"

    def workflow(command, key=None, value=None):
        nonlocal committed, staged, state

        if command == "view":
            document = staged if state == "editing" else committed
            return _copy.deepcopy({"state": state, "document": document})

        if command == "begin":
            if state != "idle":
                raise ValueError("begin requires idle state")
            staged = _copy.deepcopy(committed)
            state = "editing"
            return None

        if command == "put":
            if state != "editing":
                raise ValueError("put requires editing state")
            staged[key] = _copy.deepcopy(value)
            return None

        if command == "commit":
            if state != "editing":
                raise ValueError("commit requires editing state")
            committed = staged
            staged = None
            state = "idle"
            return _copy.deepcopy(committed)

        if command == "rollback":
            if state != "editing":
                raise ValueError("rollback requires editing state")
            staged = None
            state = "idle"
            return _copy.deepcopy(committed)

        raise ValueError("unknown command")

    return workflow

import copy as _copy


def make_job_registry():
    jobs = {}

    def dispatch(job_id, operation, value=None):
        if operation == "create":
            if job_id in jobs:
                raise ValueError("job already exists")
            jobs[job_id] = {"state": "collecting", "parts": []}
            return None

        if job_id not in jobs:
            raise KeyError(job_id)

        job = jobs[job_id]

        if operation == "get":
            return _copy.deepcopy(job)

        if operation == "add":
            if job["state"] != "collecting":
                raise ValueError("add requires collecting state")
            job["parts"].append(_copy.deepcopy(value))
            return None

        if operation == "finalize":
            if job["state"] != "collecting":
                raise ValueError("finalize requires collecting state")
            job["state"] = "finalized"
            return _copy.deepcopy(job["parts"])

        if operation == "cancel":
            if job["state"] != "collecting":
                raise ValueError("cancel requires collecting state")
            job["state"] = "cancelled"
            job["parts"] = []
            return None

        raise ValueError("unknown operation")

    return dispatch

class ParcelWorkflow:
    _TRANSITIONS = {
        ("created", "pack"): "packed",
        ("packed", "ship"): "shipped",
        ("shipped", "deliver"): "delivered",
        ("delivered", "reopen"): "shipped",
    }

    def __init__(self):
        self.state = "created"
        self.transition_count = 0
        self._completed = {}

    def apply(self, command_id, action):
        if command_id in self._completed:
            return self._completed[command_id]

        key = (self.state, action)
        if key not in self._TRANSITIONS:
            raise ValueError("invalid transition")

        self.state = self._TRANSITIONS[key]
        self.transition_count += 1
        result = (self.state, self.transition_count)
        self._completed[command_id] = result
        return result

