def canonical_search_key(text):
    sanitized = "".join(
        "�" if 0xD800 <= ord(char) <= 0xDFFF else char
        for char in text
    )
    normalized = unicodedata.normalize("NFKD", sanitized).casefold()

    output = []
    separator_pending = False
    for char in normalized:
        category = unicodedata.category(char)
        if category.startswith("M"):
            continue
        if category.startswith(("L", "N")) or char == "�":
            if separator_pending and output:
                output.append(" ")
            output.append(char)
            separator_pending = False
        elif output:
            separator_pending = True

    return "".join(output)

