use std::collections::VecDeque;

pub fn rolling_totals(batches: &[Vec<i64>], width: usize) -> Vec<Vec<i128>> {
    if width == 0 {
        return batches.iter().map(|_| Vec::new()).collect();
    }

    let mut result = Vec::with_capacity(batches.len());
    for batch in batches {
        let mut window: VecDeque<i128> = VecDeque::new();
        let mut sum = 0i128;
        let mut output = Vec::with_capacity(batch.len());
        for &value in batch {
            let value = i128::from(value);
            window.push_back(value);
            sum += value;
            if window.len() > width {
                if let Some(removed) = window.pop_front() {
                    sum -= removed;
                }
            }
            output.push(sum);
        }
        result.push(output);
    }
    result
}

pub fn delta_encode_channels(channels: &[Vec<i64>]) -> Vec<Vec<i128>> {
    let mut encoded = Vec::with_capacity(channels.len());
    for channel in channels {
        let mut previous = 0i128;
        let mut output = Vec::with_capacity(channel.len());
        for &sample in channel {
            let current = i128::from(sample);
            output.push(current - previous);
            previous = current;
        }
        encoded.push(output);
    }
    encoded
}

