pub fn folded_inventory(input: &str) -> Vec<(char, usize)> {
    let mut inventory: Vec<(char, usize)> = Vec::new();

    for ch in input.chars() {
        if ch.is_whitespace() {
            continue;
        }

        for folded in ch.to_lowercase() {
            if let Some((_, count)) = inventory.iter_mut().find(|(seen, _)| *seen == folded) {
                *count += 1;
            } else {
                inventory.push((folded, 1));
            }
        }
    }

    inventory
}

pub fn group_words_by_length(input: &str) -> Vec<(usize, Vec<String>)> {
    let mut groups: Vec<(usize, Vec<String>)> = Vec::new();

    for word in input.split(char::is_whitespace).filter(|word| !word.is_empty()) {
        let length = word.chars().count();
        if let Some((_, words)) = groups.iter_mut().find(|(seen, _)| *seen == length) {
            words.push(word.to_owned());
        } else {
            groups.push((length, vec![word.to_owned()]));
        }
    }

    groups
}

The function below is intended to compact each fragment independently. Within each fragment, every maximal nonempty run of Unicode whitespace, as identified by `char::is_whitespace()`, must become one ASCII space. Non-whitespace Unicode scalar values must be copied unchanged, including any leading or trailing compacted space.

State used to recognize a whitespace run must be isolated per fragment. The implementation incorrectly carries that state across fragment boundaries, so a leading whitespace run can disappear based on how the preceding fragment ended.

Repair the implementation and return a complete `solution.rs` with the same public API. Use only the Rust standard library. Do not add a `main` function or perform filesystem, network, clock, or random operations.

```rust
pub fn compact_fragments(fragments: &[&str]) -> Vec<String> {
    let mut output = Vec::with_capacity(fragments.len());
    let mut in_whitespace = false;

    for fragment in fragments {
        let mut compacted = String::new();
        for ch in fragment.chars() {
            if ch.is_whitespace() {
                if !in_whitespace {
                    compacted.push(' ');
                    in_whitespace = true;
                }
            } else {
                compacted.push(ch);
                in_whitespace = false;
            }
        }
        output.push(compacted);
    }

    output
}
